const int banyaknyaBaris = 73;
const int panjangPerBaris = 261;
void tampilkanKhusus(std::string teks){
    int PosisiBarisYangDitampilkan = 0;
    std::cout << "\033[H";
    for(int i = 0; i < banyaknyaBaris; i++){
        std::string barisYangDitampilkan = teks.substr(PosisiBarisYangDitampilkan, panjangPerBaris);
        std::cout << barisYangDitampilkan << std::flush;
        PosisiBarisYangDitampilkan+=panjangPerBaris;
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
}

void tampilkanMetodeYangDipilihSaatIni(pilihCara metode){
    if(metode == null){
        tampilkanKhusus(pilihan[0]);
    }
    else if(metode == random){
        tampilkanCepat(pilihan[1]);
    }
    else if(metode == manual){
        tampilkanCepat(pilihan[2]);
    }
}